WITH reason_agg AS ( SELECT cp.cp_catalog_page_id AS cp_id, cp.cp_department, r.r_reason_desc, cd.cd_gender, SUM(cr.cr_return_quantity) AS total_quantity, MAX(cr.cr_return_amount) AS max_return_amount FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_return_tax > 0 GROUP BY cp.cp_catalog_page_id, cp.cp_department, r.r_reason_desc, cd.cd_gender ), ranked_reason AS ( SELECT cp_id, cp_department, r_reason_desc, cd_gender, total_quantity, max_return_amount, ROW_NUMBER() OVER (PARTITION BY r_reason_desc ORDER BY max_return_amount DESC) AS rn_max FROM reason_agg ) SELECT cp_id, cp_department, r_reason_desc, cd_gender, total_quantity, max_return_amount, CASE WHEN rn_max <= 1 THEN 'Peak Return' ELSE 'Other' END AS peak_category FROM ranked_reason WHERE total_quantity BETWEEN 5 AND 50 ORDER BY max_return_amount DESC
